// 中心擴展：每個字元（奇數長度）與每個間隙（偶數長度）都當作中心
// 時間複雜度: O(n²)，空間複雜度: O(1)（不含輸出）
static int expand(char* s, int n, int l, int r) {
    while (l >= 0 && r < n && s[l] == s[r]) {
        l--;
        r++;
    }
    return r - l - 1;                        // 回文長度
}

char* longestPalindrome(char* s) {
    int n = strlen(s), start = 0, maxLen = 0;
    for (int i = 0; i < n; i++) {
        int a = expand(s, n, i, i), b = expand(s, n, i, i + 1);
        int len = a > b ? a : b;
        if (len > maxLen) {
            maxLen = len;
            start = i - (len - 1) / 2;
        }
    }
    char* ans = malloc(maxLen + 1);
    memcpy(ans, s + start, maxLen);
    ans[maxLen] = '\0';
    return ans;
}

